-- Venue Live Guest "Isra Mikraj & Maulid Nabi". Aditif & idempoten. Jalankan SETELAH admin-live-event-aqiqah.sql (jenis acara isramikraj), admin-live-theme.sql, admin-live-decor.sql, admin-live-decor-avatars.sql, dan admin-live-decor-garden-layout.sql (skrip tata letak itu melewati venue ini karena ukuran/posisi dekornya diatur sendiri).
insert into public.live_venues (key, name, event_type, areas, max_guests, active, sort, bg_pos, nm_theme)
select 'isramikraj', 'Isra Mikraj & Maulid Nabi', 'isramikraj', coalesce((select areas from public.live_venues where key = 'little-ballerina'), '[]'::jsonb), 300, false, 121, 'center 38%',
  $t${"name":"Isra Mikraj","orn":"diamond","ui":{"ivory":"#FBF3E2","white":"#FFFFFF","soft":"#EEDFF2","soft2":"#C9A8D8","accent":"#5B2A86","deep":"#2E1347","ink":"#2A1636","mute":"#7A6488","line":"#DCC8E6","serif":"\"Cormorant Garamond\",serif","sans":"Inter,system-ui,sans-serif","rad":18,"btnr":14,"btnt":"none","btnls":".02em"},"mono":{"font":"\"Cormorant Garamond\",serif","it":0,"paper":"#FFFAF0","ink":"#2A1636","accent":"#5B2A86","gold":"#C9A227","leaf":"#EEDFF2","hbg":"rgba(251,243,226,.94)","hline":"#C9A8D8","motif":"diamond"},"hud":{"bg":"rgba(46,19,71,.86)","acc":"#F2D98A","on":"#2A1636"},"scr":{"wine":"#2E1347","veil":"251,243,226"}}$t$::jsonb
where not exists (select 1 from public.live_venues where key = 'isramikraj');
